{
  "datasets": [
    {
      "name": "nls_ses_processed.csv",
      "description": "This dataset contains social background factors (race, gender, and socioeconomic status) and academic resources at the time of secondary school graduation (standardized test scores, class rank, and curriculum) for the participants of the NLS.",
      "columns": {
        "raw": [
          {
            "name": "CASE ID",
            "description": "Unique ID of each respondent"
          },
          {
            "name": "SAMPLE_RACE",
            "description": "Race of the respondent (Hispanic, Black or White)"
          },
          {
            "name": "SAMPLE_SEX",
            "description": "Sex of the respondent (Male or Female)"
          },
          {
            "name": "FAMILY SIZE OF SAMPLE",
            "description": "Family size of the respondent"
          },
          {
            "name": "ABILITY: COMPOSITE OF ASVAB SCORE",
            "description": "Composite variable created by summing following variables:\n\nASVAB - Arithmetic Reasoning Z Score (rounded), 1981\nASVAB - Word Knowledge Z Score (rounded), 1981\nASVAB - Paragraph Comprehension Z Score (rounded), 1981\nASVAB - Mathematics Knowledge Z Score (rounded), 1981"
          },
          {
            "name": "BA DEGREE COMPLETED",
            "description": "Boolean variable that equals 1 if the BA Degree was completed by the respondent else 0"
          },
          {
            "name": "PERCENTILE IN CLASS",
            "description": "Respondent's percentile in the class that he attended in school last year"
          },
          {
            "name": "SES",
            "description": "Socioeconomic Status of the respondent"
          }
        ]
      }
    }
  ]
}
